import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in), 1 << 16);
        int n = Integer.parseInt(br.readLine().trim());
        HashMap<String, String> passwords = new HashMap<>(n * 2);
        HashSet<String> online = new HashSet<>();
        StringBuilder out = new StringBuilder(n * 24);
        for (int i = 0; i < n; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            String op = st.nextToken(), name = st.nextToken();
            if (op.equals("register")) {
                String password = st.nextToken();
                if (passwords.putIfAbsent(name, password) == null) out.append("Registered Successfully\n");
                else out.append("Username already exists\n");
            } else if (op.equals("login")) {
                String password = st.nextToken();
                // Exists, password matches and not already online; failures change nothing.
                if (!online.contains(name) && password.equals(passwords.get(name))) {
                    online.add(name);
                    out.append("Logged In Successfully\n");
                } else out.append("Login Unsuccessful\n");
            } else {
                if (online.remove(name)) out.append("Logged Out Successfully\n");
                else out.append("Logout Unsuccessful\n");
            }
        }
        PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out), 1 << 16));
        pw.print(out);
        pw.flush();
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() string { sc.Scan(); return sc.Text() }
	n, _ := strconv.Atoi(next())
	type account struct {
		password string
		online   bool
	}
	users := make(map[string]*account, n)
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	for i := 0; i < n; i++ {
		op, name := next(), next()
		switch op {
		case "register":
			password := next()
			if _, ok := users[name]; ok {
				w.WriteString("Username already exists\n")
			} else {
				users[name] = &account{password: password}
				w.WriteString("Registered Successfully\n")
			}
		case "login":
			password := next()
			// Exists, password matches and not already online; failures change nothing.
			if u, ok := users[name]; ok && !u.online && u.password == password {
				u.online = true
				w.WriteString("Logged In Successfully\n")
			} else {
				w.WriteString("Login Unsuccessful\n")
			}
		default:
			if u, ok := users[name]; ok && u.online {
				u.online = false
				w.WriteString("Logged Out Successfully\n")
			} else {
				w.WriteString("Logout Unsuccessful\n")
			}
		}
	}
}
